SELECT now() at time zone 'UTC' db_time_utc,current_database(),current_setting('transaction_read_only') read_only;
WITH r AS MATERIALIZED (SELECT id,locale,expected_item_count,result,fallback_reason FROM recommendation_request WHERE surface_version='watch-below-player-v1' AND created_at>='2026-09-29T18:42:00Z' AND created_at<'2026-09-30T18:42:00Z')
SELECT r.expected_item_count,r.result,r.fallback_reason,cr.shortfall_reason,cr.nominated_count,cr.deduplicated_count,cr.rejected_count,cr.ordered_count,cr.composed_count,count(*) requests FROM r LEFT JOIN recommendation_candidate_run cr ON cr.request_id=r.id GROUP BY 1,2,3,4,5,6,7,8,9 ORDER BY requests DESC;
WITH r AS MATERIALIZED (SELECT id,locale,expected_item_count,result,fallback_reason FROM recommendation_request WHERE surface_version='watch-below-player-v1' AND created_at>='2026-09-29T18:42:00Z' AND created_at<'2026-09-30T18:42:00Z')
SELECT locale,count(*) requests,count(*) FILTER(WHERE expected_item_count=0) empty,count(*) FILTER(WHERE expected_item_count BETWEEN 1 AND 5) partial,count(*) FILTER(WHERE expected_item_count=6) full,count(*) FILTER(WHERE expected_item_count=0 AND fallback_reason='no_candidates') empty_no_candidates,count(*) FILTER(WHERE expected_item_count=0 AND fallback_reason='seed_embedding_unavailable') empty_no_seed FROM r GROUP BY 1 ORDER BY empty DESC,partial DESC,requests DESC;
SELECT p.revision,p.updated_at,g.version,g.created_at,g.sealed_at,pool.locale,pool.audio_language_slug,cardinality(pool.video_ids) starters FROM recommendation_curated_pointer p JOIN recommendation_curated_generation g ON g.id=p.generation_id JOIN recommendation_curated_pool pool ON pool.generation_id=g.id WHERE pool.pool_key='start' ORDER BY pool.locale,pool.audio_language_slug;
SELECT distinct jsonb_object_keys(trace_payload) payload_keys FROM recommendation_candidate_run WHERE created_at>='2026-09-29T18:42:00Z' AND created_at<'2026-09-30T18:42:00Z' AND trace_payload IS NOT NULL LIMIT 20;
